export const CHAPTER8_NARRATION: Readonly<Record<string, StepNarration>> = {
  "[\"A sunny car park. Put a stick in the ground — 2 metres tall.\",[\"stick = 2 m\"],null]": { src: "/audio/chapter8/8-1-001.mp3" },
  "[\"It casts a shadow. The shadow lies flat on the ground, right where your feet are, so you can measure it: 1 metre.\",[\"stick  = 2 m\",\"shadow = 1 m\"],null]": { src: "/audio/chapter8/8-1-002.mp3" },
  "[\"Beside it stands a tree. Enormous. You are certainly not climbing it — but it has a shadow too, and that you CAN measure: 6 metres.\",[\"tree shadow = 6 m\",\"tree height = ?\"],null]": { src: "/audio/chapter8/8-1-003.mp3" },
  "[\"The sun is 150 million km away, so its rays arrive parallel. They hit the stick and the tree at exactly the same angle.\",[\"same sun\",\"same angle\"],null]": { src: "/audio/chapter8/8-1-004.mp3" },
  "[\"Same angle, same right angle at the ground — so the two triangles are the same shape. Different sizes, identical shape.\",[\"△ small ~ △ big\",\"same shape\"],null]": { src: "/audio/chapter8/8-1-005.mp3" },
  "[\"Same shape forces the same ratio. Work it out on the stick, where you know both numbers.\",[\"height ÷ shadow\",\"= 2 ÷ 1\",\"= 2\"],null]": { src: "/audio/chapter8/8-1-006.mp3" },
  "[\"So the tree must obey it too. Its shadow is 6 m, so its height ÷ 6 = 2.\",[\"h ÷ 6 = 2\",\"h = 2 × 6\"],null]": { src: "/audio/chapter8/8-1-007.mp3" },
  "[\"Twelve metres. You measured something lying on the ground and learned a height you could never reach — that is the whole of trigonometry, in one car park.\",[\"h = 12 m\"],\"the tree is 12 m\"]": { src: "/audio/chapter8/8-1-008.mp3" },
  "[\"QUESTION — NCERT Fig. 8.2: A girl sits on a balcony above a river, looking down at a flower pot on the far bank. If she knows how high she is sitting, can she find the width of the river?\",[\"known: her height\",\"find: river width\"],null]": { src: "/audio/chapter8/8-1-009.mp3" },
  "[\"APPROACH — find the right triangle hiding in the scene, then check which side is unknown and whether the two things you can measure sit in the same triangle.\",[\"1. find the triangle\",\"2. name the sides\",\"3. check what's known\"],null]": { src: "/audio/chapter8/8-1-010.mp3" },
  "[\"She is sitting on a balcony above the water, looking down at a flower pot on the far bank.\",[\"her height = known\",\"river width = ?\"],null]": { src: "/audio/chapter8/8-1-011.mp3" },
  "[\"Find the right triangle. Her height above the water is vertical; the river's width is horizontal; they meet at 90°.\",[\"vertical  = her height\",\"horizontal = the width\"],null]": { src: "/audio/chapter8/8-1-012.mp3" },
  "[\"Her line of sight, down to the flower pot, joins the top of the vertical side to the far end of the horizontal one.\",[\"third side =\",\"the line of sight\"],null]": { src: "/audio/chapter8/8-1-013.mp3" },
  "[\"Now check the pattern: she knows one length and can measure one angle. The unknown is the side she cannot walk along.\",[\"known: height\",\"known: angle\",\"unknown: width\"],null]": { src: "/audio/chapter8/8-1-014.mp3" },
  "[\"So yes. And notice this is the tower problem lying on its side — there the vertical was unknown, here it is the horizontal.\",[\"1 length + 1 angle\",\"⇒ the third side\"],\"yes — the width follows\"]": { src: "/audio/chapter8/8-1-015.mp3" },
  "[\"A student stands on the ground looking up at the top of the Qutub Minar. Right now this is a photograph, not a maths problem.\",[],null]": { src: "/audio/chapter8/8-1-016.mp3" },
  "[\"Question one — what is vertical? The Minar. It rises straight up out of the ground, and it is the height we want.\",[\"vertical =\",\"the height, h\"],null]": { src: "/audio/chapter8/8-1-017.mp3" },
  "[\"Question two — what is horizontal? The ground from the student's feet to the base of the tower. Flat, walkable, measurable.\",[\"horizontal =\",\"the ground distance\"],null]": { src: "/audio/chapter8/8-1-018.mp3" },
  "[\"Where those two meet, at the foot of the tower, is exactly 90°. Nobody built that corner — it is what happens when something vertical stands on something flat.\",[\"vertical ⊥ horizontal\",\"= 90°, free\"],null]": { src: "/audio/chapter8/8-1-019.mp3" },
  "[\"Question three — what joins them? The line of sight, straight from the student's eye to the top.\",[\"third side =\",\"the line of sight\"],null]": { src: "/audio/chapter8/8-1-020.mp3" },
  "[\"And there it is: a right triangle nobody drew, hiding in a holiday photograph.\",[\"a right triangle\"],null]": { src: "/audio/chapter8/8-1-021.mp3" },
  "[\"Look at what you have. Two sides you can get at — the ground distance and the angle you look up through — and one you cannot: the height.\",[\"can measure: distance\",\"can measure: angle\",\"cannot reach: h\"],\"2 you can · 1 you can't\"]": { src: "/audio/chapter8/8-1-022.mp3" },
  "[\"QUESTION — NCERT Fig. 8.2: A girl on a balcony looks down at a flower pot on the far bank of a river. Find the hidden right triangle.\",[\"find: the triangle\"],null]": { src: "/audio/chapter8/8-1-023.mp3" },
  "[\"APPROACH — run the same three questions as before: what is vertical, what is horizontal, and what joins them.\",[\"1. vertical?\",\"2. horizontal?\",\"3. what joins?\"],null]": { src: "/audio/chapter8/8-1-024.mp3" },
  "[\"A different scene entirely — no tower, and she is looking down rather than up.\",[],null]": { src: "/audio/chapter8/8-1-025.mp3" },
  "[\"Run the same three questions anyway. Vertical: her height above the water. Horizontal: the width of the river.\",[\"vertical  = her height\",\"horizontal = the width\"],null]": { src: "/audio/chapter8/8-1-026.mp3" },
  "[\"Joining them: her line of sight, down to the flower pot. They meet at 90°, exactly as before.\",[\"third side =\",\"the line of sight\"],null]": { src: "/audio/chapter8/8-1-027.mp3" },
  "[\"Same triangle, rotated and given a new story. But notice what swapped — in the Minar the vertical was unknown; here it is the horizontal.\",[\"Minar: h unknown\",\"river: width unknown\"],\"same triangle, rotated\"]": { src: "/audio/chapter8/8-1-028.mp3" },
  "[\"QUESTION — when does the three-question method FAIL? Three traps the exam will try on you.\",[\"trap 1: not vertical\",\"trap 2: not horizontal\",\"trap 3: eye height\"],null]": { src: "/audio/chapter8/8-1-029.mp3" },
  "[\"Trap one — a leaning tower. If the thing is not vertical, that corner is not 90°, and none of this applies.\",[\"not vertical\",\"⇒ no right angle\"],null]": { src: "/audio/chapter8/8-1-030.mp3" },
  "[\"Trap two — sloping ground. Stand on a hill and the ground is not horizontal, so your right angle has quietly vanished.\",[\"not horizontal\",\"⇒ no right angle\"],null]": { src: "/audio/chapter8/8-1-031.mp3" },
  "[\"Trap three, and this one catches almost everybody — your eye is not on the floor. The line of sight starts about a metre and a half up.\",[\"eye ≈ 1.5 m up\"],null]": { src: "/audio/chapter8/8-1-032.mp3" },
  "[\"So the triangle you actually drew gives the height ABOVE EYE LEVEL. You have to add yourself back on at the end.\",[\"h from triangle\",\"+ your eye height\",\"= the real height\"],\"add yourself back on\"]": { src: "/audio/chapter8/8-1-033.mp3" },
  "[\"Here is triangle ABC, standing on the ground. The right angle is at B.\",[],null]": { src: "/audio/chapter8/8-2-001.mp3" },
  "[\"Find the right angle first. Look straight across from it — that side is the hypotenuse.\",[\"hypotenuse = AC\",\"the longest side\"],null]": { src: "/audio/chapter8/8-2-002.mp3" },
  "[\"Now choose an acute angle to work from. Take angle A, at the bottom right.\",[\"naming from A\"],null]": { src: "/audio/chapter8/8-2-003.mp3" },
  "[\"Which side faces A without touching it? BC. That is the opposite side.\",[\"hypotenuse = AC\",\"opposite  = BC\"],null]": { src: "/audio/chapter8/8-2-004.mp3" },
  "[\"Angle A has two arms, AB and AC. AC is already the hypotenuse, so the adjacent side is AB.\",[\"hypotenuse = AC\",\"opposite  = BC\",\"adjacent  = AB\"],null]": { src: "/audio/chapter8/8-2-005.mp3" },
  "[\"All three named — and every one of them was decided by the right angle plus the angle you chose.\",[\"hypotenuse = AC\",\"opposite  = BC\",\"adjacent  = AB\"],\"3 sides, 3 names\"]": { src: "/audio/chapter8/8-2-006.mp3" },
  "[\"QUESTION — NCERT Exercise 8.1, Q1(i): In triangle ABC, right-angled at B, AB = 24 cm and BC = 7 cm. Find sin A and cos A.\",[\"given:\",\"AB = 24 cm\",\"BC = 7 cm\",\"find: sin A, cos A\"],null]": { src: "/audio/chapter8/8-2-007.mp3" },
  "[\"APPROACH — a right triangle's third side always comes from Pythagoras. Get it first, then sort the sides into roles, then read the ratios off.\",[\"1. third side\",\"2. name the roles\",\"3. read the ratios\"],null]": { src: "/audio/chapter8/8-2-008.mp3" },
  "[\"We are given two sides. Before anything else, find the third.\",[\"AB = 24\",\"BC = 7\",\"AC = ?\"],null]": { src: "/audio/chapter8/8-2-009.mp3" },
  "[\"Pythagoras on the two legs.\",[\"AC² = 24² + 7²\",\"AC² = 576 + 49\",\"AC² = 625\"],null]": { src: "/audio/chapter8/8-2-010.mp3" },
  "[\"So the hypotenuse is 25 cm. (7-24-25 is a triple worth memorising.)\",[\"AC = √625\",\"AC = 25 cm\"],null]": { src: "/audio/chapter8/8-2-011.mp3" },
  "[\"Now sort the three lengths into their roles for angle A.\",[\"opposite  BC = 7\",\"adjacent  AB = 24\",\"hypotenuse AC = 25\"],null]": { src: "/audio/chapter8/8-2-012.mp3" },
  "[\"Sine is opposite over hypotenuse.\",[\"sin A = opp / hyp\",\"sin A = 7 / 25\"],null]": { src: "/audio/chapter8/8-2-013.mp3" },
  "[\"Cosine is adjacent over hypotenuse. Both came out below 1, and the hypotenuse was the biggest number — the checks pass.\",[\"cos A = adj / hyp\",\"cos A = 24 / 25\"],\"sin A = 7/25 · cos A = 24/25\"]": { src: "/audio/chapter8/8-2-014.mp3" },
  "[\"The same triangle as before, named from angle A at the bottom right.\",[\"from A:\",\"opposite  BC\",\"adjacent  AB\"],null]": { src: "/audio/chapter8/8-2-015.mp3" },
  "[\"Now walk across to angle C, at the top. Nothing about the triangle changes — only where you stand.\",[\"moving to C ...\"],null]": { src: "/audio/chapter8/8-2-016.mp3" },
  "[\"BC touches C, so it cannot be opposite C any more. It has become the adjacent side.\",[\"from C:\",\"adjacent  BC\"],null]": { src: "/audio/chapter8/8-2-017.mp3" },
  "[\"And AB, which was adjacent to A, is the side that faces C without touching it — so AB is now opposite.\",[\"from C:\",\"opposite  AB\",\"adjacent  BC\"],null]": { src: "/audio/chapter8/8-2-018.mp3" },
  "[\"The hypotenuse never moved. The right angle at B is still where it was, so AC is still the hypotenuse.\",[\"hypotenuse = AC\",\"unchanged\"],null]": { src: "/audio/chapter8/8-2-019.mp3" },
  "[\"Two names swapped, one stayed. That is the whole rule — and it is why sin C works out equal to cos A.\",[\"sin C = AB / AC\",\"cos A = AB / AC\",\"so sin C = cos A\"],\"2 swap · 1 stays\"]": { src: "/audio/chapter8/8-2-020.mp3" },
  "[\"QUESTION — NCERT Exercise 8.1, Q1: In triangle ABC, right-angled at B, AB = 24 cm and BC = 7 cm. Find (i) sin A and cos A, (ii) sin C and cos C.\",[\"given:\",\"AB = 24, BC = 7\",\"find: A's pair\",\"and C's pair\"],null]": { src: "/audio/chapter8/8-2-021.mp3" },
  "[\"APPROACH — the two parts use the SAME triangle from two different corners. Find the third side once, then name the roles separately for A and for C.\",[\"1. third side\",\"2. roles from A\",\"3. roles from C\"],null]": { src: "/audio/chapter8/8-2-022.mp3" },
  "[\"Third side first, by Pythagoras.\",[\"AC² = 24² + 7² = 625\",\"AC = 25 cm\"],null]": { src: "/audio/chapter8/8-2-023.mp3" },
  "[\"Part (i), from angle A. Opposite is BC = 7, adjacent is AB = 24.\",[\"sin A = 7 / 25\",\"cos A = 24 / 25\"],null]": { src: "/audio/chapter8/8-2-024.mp3" },
  "[\"Part (ii) moves to angle C. Do not carry the old names over — start again from the new corner.\",[\"from C ...\"],null]": { src: "/audio/chapter8/8-2-025.mp3" },
  "[\"From C the roles swap: AB = 24 is now opposite, and CB = 7 is now adjacent.\",[\"opposite  AB = 24\",\"adjacent  BC = 7\",\"hypotenuse  25\"],null]": { src: "/audio/chapter8/8-2-026.mp3" },
  "[\"So sin C = 24/25 and cos C = 7/25 — which are exactly cos A and sin A, crossed over.\",[\"sin C = 24 / 25\",\"cos C = 7 / 25\",\"sin C = cos A ✓\"],\"sin C = 24/25 · cos C = 7/25\"]": { src: "/audio/chapter8/8-2-027.mp3" },
  "[\"QUESTION — NCERT Exercise 8.1, Q2: In triangle PQR, right-angled at Q, PQ = 12 cm and PR = 13 cm. Find tan P minus cot R.\",[\"given:\",\"PQ = 12, PR = 13\",\"find: tan P − cot R\"],null]": { src: "/audio/chapter8/8-2-028.mp3" },
  "[\"APPROACH — build each ratio separately from its own corner, then subtract. Do not assume they differ just because the names look different.\",[\"1. third side\",\"2. tan P from P\",\"3. cot R from R\",\"4. subtract\"],null]": { src: "/audio/chapter8/8-2-029.mp3" },
  "[\"Third side first — this time subtract, because we were given the hypotenuse.\",[\"QR² = 13² − 12²\",\"QR² = 169 − 144 = 25\",\"QR = 5 cm\"],null]": { src: "/audio/chapter8/8-2-030.mp3" },
  "[\"tan P wants opposite over adjacent, read from corner P.\",[\"opposite P = QR = 5\",\"adjacent P = PQ = 12\",\"tan P = 5 / 12\"],null]": { src: "/audio/chapter8/8-2-031.mp3" },
  "[\"Now cot R. Cotangent is adjacent over opposite — the other way up from tan.\",[\"cot = adj / opp\"],null]": { src: "/audio/chapter8/8-2-032.mp3" },
  "[\"From corner R the sides have swapped: QR is now adjacent and PQ is now opposite.\",[\"adjacent R = QR = 5\",\"opposite R = PQ = 12\",\"cot R = 5 / 12\"],null]": { src: "/audio/chapter8/8-2-033.mp3" },
  "[\"The same fraction, from a different corner and a different ratio. Two swaps and one flip cancel exactly.\",[\"tan P − cot R\",\"= 5/12 − 5/12\"],\"tan P − cot R = 0\"]": { src: "/audio/chapter8/8-2-034.mp3" },
  "[\"Every side already has a name. A ratio is just two of those names written as a fraction — and only three of them are worth naming.\",[\"opposite\",\"adjacent\",\"hypotenuse\"],null]": { src: "/audio/chapter8/8-2-035.mp3" },
  "[\"SOH — sine takes the side OPPOSITE the angle and puts the HYPOTENUSE underneath.\",[\"sin A = opp / hyp\",\"= BC / AC\"],null]": { src: "/audio/chapter8/8-2-036.mp3" },
  "[\"CAH — cosine swaps the opposite side for the ADJACENT one. The hypotenuse stays underneath.\",[\"cos A = adj / hyp\",\"= AB / AC\"],null]": { src: "/audio/chapter8/8-2-037.mp3" },
  "[\"TOA — tangent leaves the hypotenuse out of it completely. Opposite over adjacent, nothing else.\",[\"tan A = opp / adj\",\"= BC / AB\"],null]": { src: "/audio/chapter8/8-2-038.mp3" },
  "[\"Now watch what happens if you divide sine by cosine. Both of them carry the hypotenuse underneath.\",[\"sin A ÷ cos A\",\"= (BC/AC) ÷ (AB/AC)\",\"= (BC/AC) × (AC/AB)\"],null]": { src: "/audio/chapter8/8-2-039.mp3" },
  "[\"The hypotenuse cancels top and bottom, and what survives is opposite over adjacent — which is exactly tan A. That is one fewer thing to memorise.\",[\"= BC / AB\",\"= tan A\"],\"tan A = sin A / cos A\"]": { src: "/audio/chapter8/8-2-040.mp3" },
  "[\"One notation warning that costs marks every year: sin A is ONE symbol, not sin multiplied by A. And sin²A means (sin A)² — find the number first, then square it.\",[\"sin A ≠ sin × A\",\"sin²A = (sin A)²\"],null]": { src: "/audio/chapter8/8-2-041.mp3" },
  "[\"READ & TRANSLATE — △ABC is right-angled at B, with AB = 24 cm and BC = 7 cm. The question wants two ratios of angle A, so both need a hypotenuse.\",[\"right angle at B\",\"AB = 24, BC = 7\",\"find sin A, cos A\"],null]": { src: "/audio/chapter8/8-2-042.mp3" },
  "[\"CHOOSE THE PATTERN — SOH and CAH both need the hypotenuse AC, and AC is not given. So Pythagoras comes first, then the ratios.\",[\"1. Pythagoras → AC\",\"2. sin A = opp/hyp\",\"3. cos A = adj/hyp\"],null]": { src: "/audio/chapter8/8-2-043.mp3" },
  "[\"SUBSTITUTE — the two legs are 24 and 7, and the hypotenuse faces the right angle at B.\",[\"AC² = AB² + BC²\",\"AC² = 24² + 7²\"],null]": { src: "/audio/chapter8/8-2-044.mp3" },
  "[\"CALCULATE, LINE 1 — square each leg and add, then take the positive square root.\",[\"= 576 + 49\",\"= 625\",\"AC = √625 = 25\"],null]": { src: "/audio/chapter8/8-2-045.mp3" },
  "[\"CALCULATE, LINE 2 — now read the ratios off angle A. Opposite A is BC = 7; adjacent to A is AB = 24.\",[\"sin A = BC/AC = 7/25\",\"cos A = AB/AC = 24/25\"],null]": { src: "/audio/chapter8/8-2-046.mp3" },
  "[\"SANITY CHECK — both answers must be below 1, because the hypotenuse is the longest side. They are. And 7² + 24² = 625 = 25² confirms the triangle closes.\",[\"7/25 < 1 ✓\",\"24/25 < 1 ✓\",\"49 + 576 = 625 ✓\"],null]": { src: "/audio/chapter8/8-2-047.mp3" },
  "[\"FINAL ANSWER — sin A = 7/25 and cos A = 24/25.\",[\"sin A = 7/25\",\"cos A = 24/25\"],\"sin A = 7/25 · cos A = 24/25\"]": { src: "/audio/chapter8/8-2-048.mp3" },
  "[\"READ & TRANSLATE — you are given the hypotenuse and the side adjacent to θ. All three ratios are wanted, so the missing opposite side has to be found first.\",[\"hyp = 13\",\"adj = 5\",\"opp = ?\"],null]": { src: "/audio/chapter8/8-2-049.mp3" },
  "[\"CHOOSE THE PATTERN — cos θ is available immediately from CAH, but sine and tangent both need the opposite side. Pythagoras supplies it.\",[\"cos θ = adj/hyp now\",\"opp from Pythagoras\",\"then sin and tan\"],null]": { src: "/audio/chapter8/8-2-050.mp3" },
  "[\"SUBSTITUTE — rearrange Pythagoras to make the unknown leg the subject.\",[\"opp² = hyp² − adj²\",\"opp² = 13² − 5²\"],null]": { src: "/audio/chapter8/8-2-051.mp3" },
  "[\"CALCULATE, LINE 1 — subtract, then take the positive root.\",[\"= 169 − 25\",\"= 144\",\"opp = 12\"],null]": { src: "/audio/chapter8/8-2-052.mp3" },
  "[\"CALCULATE, LINE 2 — with all three sides known, read each ratio straight off SOH CAH TOA.\",[\"sin θ = 12/13\",\"cos θ = 5/13\",\"tan θ = 12/5\"],null]": { src: "/audio/chapter8/8-2-053.mp3" },
  "[\"SANITY CHECK — sine and cosine are both under 1, as they must be. Tangent is above 1, which is allowed because it never involves the hypotenuse. And 5-12-13 is a genuine Pythagorean triple.\",[\"25 + 144 = 169 ✓\",\"sin, cos < 1 ✓\",\"tan may exceed 1 ✓\"],null]": { src: "/audio/chapter8/8-2-054.mp3" },
  "[\"FINAL ANSWER — sin θ = 12/13, cos θ = 5/13, tan θ = 12/5.\",[\"sin θ = 12/13\",\"cos θ = 5/13\",\"tan θ = 12/5\"],\"12/13 · 5/13 · 12/5\"]": { src: "/audio/chapter8/8-2-055.mp3" },
  "[\"Here is the question this whole chapter rests on: if you redraw the triangle bigger, does sin A change?\",[\"same angle A\",\"bigger triangle\",\"same sin A?\"],null]": { src: "/audio/chapter8/8-2-056.mp3" },
  "[\"Take a smaller right triangle sharing the very same angle A. Both contain a right angle, and both contain A.\",[\"shared angle A\",\"both right-angled\"],null]": { src: "/audio/chapter8/8-2-057.mp3" },
  "[\"Two matching angles is already enough — that is the AA criterion from Chapter 6. The triangles are SIMILAR.\",[\"angle A = angle A\",\"90° = 90°\",\"⇒ similar by AA\"],null]": { src: "/audio/chapter8/8-2-058.mp3" },
  "[\"Similar triangles have proportional sides. Every side of the big triangle is the same multiple k of the matching small one.\",[\"big = k × small\",\"for every side\"],null]": { src: "/audio/chapter8/8-2-059.mp3" },
  "[\"So write sin A in the big triangle and substitute. The k appears above AND below the line.\",[\"sin A = (k × opp) / (k × hyp)\"],null]": { src: "/audio/chapter8/8-2-060.mp3" },
  "[\"The k cancels. The ratio is identical in both triangles — and the same argument works for all six ratios.\",[\"= opp / hyp\",\"size cancels out\"],\"the ratio depends on A alone\"]": { src: "/audio/chapter8/8-2-061.mp3" },
  "[\"That is why 'sin 30°' can be written with no triangle mentioned anywhere. The angle alone fixes the number.\",[\"sin 30° = 1/2\",\"no triangle needed\"],null]": { src: "/audio/chapter8/8-2-062.mp3" },
  "[\"READ & TRANSLATE — two right triangles, one exactly double the other. Show the sine of the shared angle is the same number in both.\",[\"small: 3, 4, 5\",\"big: 6, 8, 10\"],null]": { src: "/audio/chapter8/8-2-063.mp3" },
  "[\"CHOOSE THE PATTERN — compute sin A separately in each triangle and compare. No identity is needed; this is definition and cancellation.\",[\"sin A = opp / hyp\",\"compute twice, compare\"],null]": { src: "/audio/chapter8/8-2-064.mp3" },
  "[\"SUBSTITUTE — in the small triangle the side opposite A is 3 and the hypotenuse is 5.\",[\"sin A = 3 / 5\"],null]": { src: "/audio/chapter8/8-2-065.mp3" },
  "[\"CALCULATE, LINE 1 — in the big triangle every length has doubled, so opposite is 6 and hypotenuse is 10.\",[\"sin A = 6 / 10\"],null]": { src: "/audio/chapter8/8-2-066.mp3" },
  "[\"CALCULATE, LINE 2 — cancel the common factor 2 from the second fraction.\",[\"6/10 = (2×3)/(2×5)\",\"= 3/5\"],null]": { src: "/audio/chapter8/8-2-067.mp3" },
  "[\"SANITY CHECK — both triangles satisfy Pythagoras, and the two sines agree exactly. The doubling factor cancelled, as similarity predicted.\",[\"9 + 16 = 25 ✓\",\"36 + 64 = 100 ✓\",\"3/5 = 6/10 ✓\"],null]": { src: "/audio/chapter8/8-2-068.mp3" },
  "[\"FINAL ANSWER — sin A = 3/5 in both. Scaling a triangle never changes a trigonometric ratio.\",[\"sin A = 3/5 either way\"],\"size cancels — sin A = 3/5\"]": { src: "/audio/chapter8/8-2-069.mp3" },
  "[\"You already have three ratios. The other three are not new geography — they are the same three fractions turned upside down.\",[\"sin, cos, tan\",\"flip each one\"],null]": { src: "/audio/chapter8/8-2-070.mp3" },
  "[\"Turn sine over and you get COSECANT. Hypotenuse on top, opposite underneath.\",[\"sin A = opp/hyp\",\"cosec A = hyp/opp\"],null]": { src: "/audio/chapter8/8-2-071.mp3" },
  "[\"Turn cosine over and you get SECANT.\",[\"cos A = adj/hyp\",\"sec A = hyp/adj\"],null]": { src: "/audio/chapter8/8-2-072.mp3" },
  "[\"Turn tangent over and you get COTANGENT.\",[\"tan A = opp/adj\",\"cot A = adj/opp\"],null]": { src: "/audio/chapter8/8-2-073.mp3" },
  "[\"Watch the pairings — they are deliberately confusing. Cosecant flips SINE, not cosine. Secant flips COSINE, not sine.\",[\"sin ↔ cosec\",\"cos ↔ sec\",\"tan ↔ cot\"],null]": { src: "/audio/chapter8/8-2-074.mp3" },
  "[\"Because each pair is a reciprocal, multiplying a pair always gives exactly 1.\",[\"sin A × cosec A = 1\",\"cos A × sec A = 1\",\"tan A × cot A = 1\"],\"each pair multiplies to 1\"]": { src: "/audio/chapter8/8-2-075.mp3" },
  "[\"READ & TRANSLATE — one ratio is given. Its reciprocal needs no work at all; the other two need the third side.\",[\"sin θ = 8/17\",\"find cosec θ, cos θ, sec θ\"],null]": { src: "/audio/chapter8/8-2-076.mp3" },
  "[\"CHOOSE THE PATTERN — cosec θ is just sin θ flipped. For cos θ you need the adjacent side, so Pythagoras.\",[\"cosec θ = 1 / sin θ\",\"adjacent via Pythagoras\",\"sec θ = 1 / cos θ\"],null]": { src: "/audio/chapter8/8-2-077.mp3" },
  "[\"SUBSTITUTE — sin θ = 8/17 means opposite = 8k and hypotenuse = 17k. Flip it for the cosecant.\",[\"cosec θ = 17/8\",\"adj² = 17² − 8²\"],null]": { src: "/audio/chapter8/8-2-078.mp3" },
  "[\"CALCULATE, LINE 1 — find the adjacent side.\",[\"= 289 − 64\",\"= 225\",\"adj = 15\"],null]": { src: "/audio/chapter8/8-2-079.mp3" },
  "[\"CALCULATE, LINE 2 — now cosine, and its reciprocal.\",[\"cos θ = 15/17\",\"sec θ = 17/15\"],null]": { src: "/audio/chapter8/8-2-080.mp3" },
  "[\"SANITY CHECK — multiply each reciprocal pair and you must get 1. Also 8-15-17 satisfies Pythagoras.\",[\"(8/17)(17/8) = 1 ✓\",\"(15/17)(17/15) = 1 ✓\",\"64 + 225 = 289 ✓\"],null]": { src: "/audio/chapter8/8-2-081.mp3" },
  "[\"FINAL ANSWER — cosec θ = 17/8, cos θ = 15/17 and sec θ = 17/15.\",[\"cosec θ = 17/8\",\"cos θ = 15/17\",\"sec θ = 17/15\"],\"17/8 · 15/17 · 17/15\"]": { src: "/audio/chapter8/8-2-082.mp3" },
  "[\"Enough letters. Put real numbers on a triangle and every ratio becomes a fraction you can actually write down.\",[\"BC = 3\",\"AB = 4\",\"AC = 5\"],null]": { src: "/audio/chapter8/8-2-083.mp3" },
  "[\"First check it really is right-angled: 3² + 4² must equal 5². It does, so the little square at B is honest.\",[\"9 + 16 = 25\",\"5² = 25 ✓\"],null]": { src: "/audio/chapter8/8-2-084.mp3" },
  "[\"Work from angle A. Opposite A is BC = 3, adjacent to A is AB = 4, and the hypotenuse is AC = 5.\",[\"opp = 3\",\"adj = 4\",\"hyp = 5\"],null]": { src: "/audio/chapter8/8-2-085.mp3" },
  "[\"Now the three main ratios are pure arithmetic.\",[\"sin A = 3/5\",\"cos A = 4/5\",\"tan A = 3/4\"],null]": { src: "/audio/chapter8/8-2-086.mp3" },
  "[\"Flip each one for the other three. No new measuring needed.\",[\"cosec A = 5/3\",\"sec A = 5/4\",\"cot A = 4/3\"],null]": { src: "/audio/chapter8/8-2-087.mp3" },
  "[\"Now move to angle C and watch the swap. What was opposite is now adjacent — so sine and cosine trade values.\",[\"sin C = 4/5\",\"cos C = 3/5\",\"tan C = 4/3\"],\"sin C = cos A, cos C = sin A\"]": { src: "/audio/chapter8/8-2-088.mp3" },
  "[\"READ & TRANSLATE — all three sides are already known, so nothing has to be found. This is pure naming plus division.\",[\"BC = 3, AB = 4, AC = 5\",\"find all six for A\"],null]": { src: "/audio/chapter8/8-2-089.mp3" },
  "[\"CHOOSE THE PATTERN — SOH CAH TOA gives the first three, and flipping each gives the rest. Name the sides from angle A before writing anything.\",[\"opp = BC = 3\",\"adj = AB = 4\",\"hyp = AC = 5\"],null]": { src: "/audio/chapter8/8-2-090.mp3" },
  "[\"SUBSTITUTE — put those three numbers into the three templates.\",[\"sin A = 3/5\",\"cos A = 4/5\",\"tan A = 3/4\"],null]": { src: "/audio/chapter8/8-2-091.mp3" },
  "[\"CALCULATE, LINE 1 — invert each fraction for the reciprocal three.\",[\"cosec A = 5/3\",\"sec A = 5/4\",\"cot A = 4/3\"],null]": { src: "/audio/chapter8/8-2-092.mp3" },
  "[\"CALCULATE, LINE 2 — a useful cross-check: tan A should equal sin A ÷ cos A.\",[\"(3/5) ÷ (4/5)\",\"= (3/5) × (5/4)\",\"= 3/4 ✓\"],null]": { src: "/audio/chapter8/8-2-093.mp3" },
  "[\"SANITY CHECK — sine and cosine are both under 1 because 5 is the longest side. The reciprocals are all above 1, exactly as they must be.\",[\"3/5, 4/5 < 1 ✓\",\"5/3, 5/4 > 1 ✓\"],null]": { src: "/audio/chapter8/8-2-094.mp3" },
  "[\"FINAL ANSWER — all six ratios of angle A.\",[\"sin 3/5 · cos 4/5 · tan 3/4\",\"cosec 5/3 · sec 5/4 · cot 4/3\"],\"3/5 · 4/5 · 3/4 · 5/3 · 5/4 · 4/3\"]": { src: "/audio/chapter8/8-2-095.mp3" },
  "[\"Exam questions rarely hand you a triangle. They hand you one ratio and expect all the others. Here is the method that always works.\",[\"given: one ratio\",\"wanted: the rest\"],null]": { src: "/audio/chapter8/8-2-096.mp3" },
  "[\"Say tan A = 3/4. That does NOT mean the sides are 3 and 4 — it means they are in the RATIO 3 to 4.\",[\"tan A = 3/4\",\"not lengths — a ratio\"],null]": { src: "/audio/chapter8/8-2-097.mp3" },
  "[\"So introduce a common factor k. Opposite = 3k, adjacent = 4k. Every triangle with this angle fits that description.\",[\"opp = 3k\",\"adj = 4k\"],null]": { src: "/audio/chapter8/8-2-098.mp3" },
  "[\"Pythagoras finds the hypotenuse, still carrying the k.\",[\"hyp² = (3k)² + (4k)²\",\"= 9k² + 16k² = 25k²\",\"hyp = 5k\"],null]": { src: "/audio/chapter8/8-2-099.mp3" },
  "[\"Now every ratio has k on the top and k on the bottom — so it cancels every single time.\",[\"sin A = 3k/5k = 3/5\",\"cos A = 4k/5k = 4/5\"],\"the k always cancels\"]": { src: "/audio/chapter8/8-2-100.mp3" },
  "[\"That is the whole trick: one ratio fixes the triangle up to scale, and scale never survives a ratio.\",[\"1 ratio ⇒ all 6\"],null]": { src: "/audio/chapter8/8-2-101.mp3" },
  "[\"READ & TRANSLATE — sine is opposite over hypotenuse, so 3 and 4 describe those two sides in ratio. The adjacent side is missing.\",[\"sin A = 3/4\",\"find cos A, tan A\"],null]": { src: "/audio/chapter8/8-2-102.mp3" },
  "[\"CHOOSE THE PATTERN — set opposite = 3k and hypotenuse = 4k, then use Pythagoras for the adjacent side.\",[\"opp = 3k, hyp = 4k\",\"adj² = hyp² − opp²\"],null]": { src: "/audio/chapter8/8-2-103.mp3" },
  "[\"SUBSTITUTE — put the two k-expressions into Pythagoras.\",[\"adj² = (4k)² − (3k)²\"],null]": { src: "/audio/chapter8/8-2-104.mp3" },
  "[\"CALCULATE, LINE 1 — expand and simplify, then take the root.\",[\"= 16k² − 9k²\",\"= 7k²\",\"adj = √7 k\"],null]": { src: "/audio/chapter8/8-2-105.mp3" },
  "[\"CALCULATE, LINE 2 — read off cosine and tangent; the k cancels in both.\",[\"cos A = √7k / 4k = √7/4\",\"tan A = 3k / √7k = 3/√7\"],null]": { src: "/audio/chapter8/8-2-106.mp3" },
  "[\"SANITY CHECK — cos A must be below 1, and √7 ≈ 2.65 so √7/4 ≈ 0.66. Also check sin²A + cos²A = 9/16 + 7/16 = 1.\",[\"√7/4 ≈ 0.66 < 1 ✓\",\"9/16 + 7/16 = 1 ✓\"],null]": { src: "/audio/chapter8/8-2-107.mp3" },
  "[\"FINAL ANSWER — cos A = √7/4 and tan A = 3/√7.\",[\"cos A = √7/4\",\"tan A = 3/√7\"],\"cos A = √7/4 · tan A = 3/√7\"]": { src: "/audio/chapter8/8-2-108.mp3" },
  "[\"READ & TRANSLATE — you are given one side and the DIFFERENCE of the other two. That difference is the equation in disguise.\",[\"OP = 7\",\"OQ − PQ = 1\",\"find sin Q\"],null]": { src: "/audio/chapter8/8-2-109.mp3" },
  "[\"CHOOSE THE PATTERN — name the unknown. Let PQ = x, so OQ = x + 1, then let Pythagoras produce an equation in x.\",[\"PQ = x\",\"OQ = x + 1\",\"OQ² = OP² + PQ²\"],null]": { src: "/audio/chapter8/8-2-110.mp3" },
  "[\"SUBSTITUTE — the right angle is at P, so OQ is the hypotenuse.\",[\"(x + 1)² = 7² + x²\"],null]": { src: "/audio/chapter8/8-2-111.mp3" },
  "[\"CALCULATE, LINE 1 — expand the bracket. The x² terms appear on both sides and cancel, which is what makes this solvable.\",[\"x² + 2x + 1 = 49 + x²\",\"2x + 1 = 49\",\"2x = 48\"],null]": { src: "/audio/chapter8/8-2-112.mp3" },
  "[\"CALCULATE, LINE 2 — solve for x, then get both remaining sides.\",[\"x = 24\",\"PQ = 24\",\"OQ = 25\"],null]": { src: "/audio/chapter8/8-2-113.mp3" },
  "[\"CALCULATE, LINE 3 — sin Q is opposite over hypotenuse. Opposite angle Q is OP = 7.\",[\"sin Q = OP / OQ\",\"= 7 / 25\"],null]": { src: "/audio/chapter8/8-2-114.mp3" },
  "[\"SANITY CHECK — 7² + 24² = 49 + 576 = 625 = 25², and 25 − 24 = 1 as the question stated. Both conditions hold.\",[\"49 + 576 = 625 ✓\",\"25 − 24 = 1 ✓\"],null]": { src: "/audio/chapter8/8-2-115.mp3" },
  "[\"FINAL ANSWER — sin Q = 7/25.\",[\"sin Q = 7/25\"],\"sin Q = 7/25\"]": { src: "/audio/chapter8/8-2-116.mp3" },
  "[\"Some answers are impossible before you check any arithmetic. Knowing which saves you in the exam.\",[\"which values are legal?\"],null]": { src: "/audio/chapter8/8-2-117.mp3" },
  "[\"Start from the one fact that never changes: the hypotenuse faces the right angle and is the LONGEST side.\",[\"hyp > opp\",\"hyp > adj\"],null]": { src: "/audio/chapter8/8-2-118.mp3" },
  "[\"Sine puts the opposite side over the hypotenuse — a smaller number over a bigger one. So sine can never reach 1.\",[\"sin A = opp / hyp\",\"0 < sin A < 1\"],null]": { src: "/audio/chapter8/8-2-119.mp3" },
  "[\"Cosine does the same with the adjacent side, so it is capped too.\",[\"cos A = adj / hyp\",\"0 < cos A < 1\"],null]": { src: "/audio/chapter8/8-2-120.mp3" },
  "[\"But tangent never touches the hypotenuse. It compares the two legs, and either one may be longer — so tangent has NO upper limit.\",[\"tan A = opp / adj\",\"tan A > 0, unbounded\"],null]": { src: "/audio/chapter8/8-2-121.mp3" },
  "[\"Flip the capped ones and the inequality flips with them: cosec and sec are always at least 1.\",[\"cosec A ≥ 1\",\"sec A ≥ 1\"],\"sin, cos ≤ 1 · cosec, sec ≥ 1 · tan free\"]": { src: "/audio/chapter8/8-2-122.mp3" },
  "[\"READ & TRANSLATE — the claim is that tan A can never reach 1. One counter-example is enough to destroy it.\",[\"claim: tan A < 1 always\"],null]": { src: "/audio/chapter8/8-2-123.mp3" },
  "[\"CHOOSE THE PATTERN — tan A = opposite/adjacent. Neither of those is the hypotenuse, so nothing forces one to be smaller.\",[\"tan A = opp / adj\",\"no cap in the definition\"],null]": { src: "/audio/chapter8/8-2-124.mp3" },
  "[\"SUBSTITUTE — take a 60° angle, where the opposite side is the longer leg.\",[\"tan 60° = √3 / 1\"],null]": { src: "/audio/chapter8/8-2-125.mp3" },
  "[\"CALCULATE — evaluate the root.\",[\"√3 ≈ 1.732\",\"tan 60° ≈ 1.73 > 1\"],null]": { src: "/audio/chapter8/8-2-126.mp3" },
  "[\"SANITY CHECK — is this triangle legal? 1² + (√3)² = 1 + 3 = 4 = 2². Yes, and the hypotenuse 2 is still the longest side, so nothing is broken.\",[\"1 + 3 = 4 = 2² ✓\",\"hyp 2 is longest ✓\"],null]": { src: "/audio/chapter8/8-2-127.mp3" },
  "[\"FINAL ANSWER — false. tan 60° = √3 ≈ 1.73, which is greater than 1. Only sine and cosine are capped.\",[\"tan 60° = √3 > 1\"],\"FALSE — tan is unbounded\"]": { src: "/audio/chapter8/8-2-128.mp3" },
  "[\"Section 8.2 is finished. Strip it down and only three ideas actually need to survive into the exam.\",[\"three keepers\"],null]": { src: "/audio/chapter8/8-2-129.mp3" },
  "[\"KEEPER ONE — the right angle names the hypotenuse. You choose the acute angle, and that choice names opposite and adjacent.\",[\"right angle ⇒ hypotenuse\",\"your angle ⇒ opp, adj\"],null]": { src: "/audio/chapter8/8-2-130.mp3" },
  "[\"KEEPER TWO — six ratios, but really three plus their flips. SOH CAH TOA, then turn each one over.\",[\"sin ↔ cosec\",\"cos ↔ sec\",\"tan ↔ cot\"],null]": { src: "/audio/chapter8/8-2-131.mp3" },
  "[\"KEEPER THREE — the value depends on the ANGLE alone. Scale the triangle and every common factor cancels.\",[\"k cancels\",\"ratio = f(angle)\"],null]": { src: "/audio/chapter8/8-2-132.mp3" },
  "[\"Two consequences worth remembering: swapping to the other acute angle swaps sine and cosine, and one known ratio unlocks all six.\",[\"sin A = cos C\",\"1 ratio ⇒ all 6\"],\"name · flip · scale-free\"]": { src: "/audio/chapter8/8-2-133.mp3" },
  "[\"READ & TRANSLATE — two sides are given and the third is missing. The expression mixes an angle-P ratio with an angle-R ratio, so both must be named carefully.\",[\"PQ = 12, PR = 13\",\"find tan P − cot R\"],null]": { src: "/audio/chapter8/8-2-134.mp3" },
  "[\"CHOOSE THE PATTERN — the right angle is at Q, so PR is the hypotenuse. Pythagoras gives QR, then name each ratio from its own angle.\",[\"QR² = PR² − PQ²\",\"then tan P, then cot R\"],null]": { src: "/audio/chapter8/8-2-135.mp3" },
  "[\"SUBSTITUTE — insert the two known lengths.\",[\"QR² = 13² − 12²\"],null]": { src: "/audio/chapter8/8-2-136.mp3" },
  "[\"CALCULATE, LINE 1 — find the third side.\",[\"= 169 − 144\",\"= 25\",\"QR = 5\"],null]": { src: "/audio/chapter8/8-2-137.mp3" },
  "[\"CALCULATE, LINE 2 — for angle P the opposite side is QR and the adjacent is PQ.\",[\"tan P = QR / PQ\",\"= 5 / 12\"],null]": { src: "/audio/chapter8/8-2-138.mp3" },
  "[\"CALCULATE, LINE 3 — now switch to angle R. Cotangent is adjacent over opposite, and for R the adjacent side is QR while the opposite is PQ.\",[\"cot R = QR / PQ\",\"= 5 / 12\"],null]": { src: "/audio/chapter8/8-2-139.mp3" },
  "[\"SANITY CHECK — the two expressions turned out identical, which is not luck: tan of one acute angle always equals cot of the other. Also 25 + 144 = 169 ✓.\",[\"tan P = cot R always\",\"5² + 12² = 13² ✓\"],null]": { src: "/audio/chapter8/8-2-140.mp3" },
  "[\"FINAL ANSWER — tan P − cot R = 5/12 − 5/12 = 0.\",[\"5/12 − 5/12\",\"= 0\"],\"tan P − cot R = 0\"]": { src: "/audio/chapter8/8-2-141.mp3" },
  "[\"Picture a square sandwich cut corner-to-corner: each half is this right triangle. Before we label anything, predict: will its two short sides match?\",[\"PREDICT\",\"equal halves ⇒ equal legs?\"],null]": { src: "/audio/chapter8/8-3-001.mp3" },
  "[\"Reveal: yes. One corner is 90° and the diagonal splits the other two square corners equally. The angle sum confirms the remaining angle is also 45°.\",[\"180° − 90° − 45°\",\"= 45°\"],null]": { src: "/audio/chapter8/8-3-002.mp3" },
  "[\"Two equal angles means two equal sides. The triangle is isosceles, so the legs match — call each of them a.\",[\"BC = AB\",\"call each one  a\"],null]": { src: "/audio/chapter8/8-3-003.mp3" },
  "[\"Pythagoras gives the hypotenuse. Both legs are a, so the two squares are the same.\",[\"AC² = a² + a²\",\"AC² = 2a²\",\"AC = a√2\"],null]": { src: "/audio/chapter8/8-3-004.mp3" },
  "[\"Now read sin 45° off the picture: opposite over hypotenuse. The a cancels — which is why the answer is a plain number for every 45° triangle ever drawn.\",[\"sin 45° = a / (a√2)\",\"sin 45° = 1/√2\"],null]": { src: "/audio/chapter8/8-3-005.mp3" },
  "[\"cos 45° is adjacent over hypotenuse — and the adjacent side is the same length as the opposite one, so it gives the same value.\",[\"cos 45° = a / (a√2)\",\"cos 45° = 1/√2\"],null]": { src: "/audio/chapter8/8-3-006.mp3" },
  "[\"Prediction checkpoint: if opposite and adjacent are equal, should their ratio be below 1, above 1, or exactly 1? tan 45° confirms exactly 1.\",[\"tan 45° = a / a\",\"tan 45° = 1\"],null]": { src: "/audio/chapter8/8-3-007.mp3" },
  "[\"Flip each one to get the other three. Nothing new to derive — a reciprocal is just the fraction upside down.\",[\"cosec 45° = √2\",\"sec 45° = √2\",\"cot 45° = 1\"],\"sin = cos = 1/√2 · tan = 1\"]": { src: "/audio/chapter8/8-3-008.mp3" },
  "[\"READ & TRANSLATE — NCERT Exercise 8.2, Q1(ii) asks for one number. Read it as: double tan²45°, then add cos²30° and subtract sin²60°.\",[\"2 tan²45°\",\"+ cos²30°\",\"− sin²60°\"],null]": { src: "/audio/chapter8/8-3-009.mp3" },
  "[\"CHOOSE THE PATTERN — use Table 8.1 because every angle is standard. Scan first for equal values: an equal term added and subtracted will cancel.\",[\"1. scan for repeats\",\"2. substitute\",\"3. simplify\"],null]": { src: "/audio/chapter8/8-3-010.mp3" },
  "[\"SUBSTITUTE — tan 45° = 1, while cos 30° and sin 60° are both √3/2. Put those values into the original expression without changing its signs.\",[\"2(1)² + (√3/2)² − (√3/2)²\"],null]": { src: "/audio/chapter8/8-3-011.mp3" },
  "[\"CALCULATE, LINE 1 — square the equal root fractions. Each becomes 3/4.\",[\"cos²30° − sin²60°\",\"= 3/4 − 3/4\",\"= 0\"],null]": { src: "/audio/chapter8/8-3-012.mp3" },
  "[\"CALCULATE, LINE 2 — the equal fractions cancel; square 1, then multiply by 2.\",[\"= 2 × 1 + 0\",\"= 2 + 0\",\"= 2\"],null]": { src: "/audio/chapter8/8-3-013.mp3" },
  "[\"SANITY CHECK — cos 30° and sin 60° are the same positive value, so their squares must cancel. The answer must therefore be exactly 2 tan²45° = 2.\",[\"+3/4 − 3/4 = 0 ✓\",\"2(1²) = 2 ✓\"],null]": { src: "/audio/chapter8/8-3-014.mp3" },
  "[\"FINAL ANSWER — the expression equals 2.\",[\"2 tan²45° + cos²30° − sin²60°\",\"= 2\"],\"= 2\"]": { src: "/audio/chapter8/8-3-015.mp3" },
  "[\"READ & TRANSLATE — NCERT Exercise 8.2, Q2(ii) asks which option matches this fraction. The same tan²45° appears once with a minus on top and once with a plus below.\",[\"(1 − tan²45°)\",\"⁄\",\"(1 + tan²45°)\"],null]": { src: "/audio/chapter8/8-3-016.mp3" },
  "[\"CHOOSE THE PATTERN — this is direct substitution because 45° is in Table 8.1. Evaluate numerator and denominator separately so the two signs cannot get mixed up.\",[\"tan 45° = 1\",\"so tan²45° = 1\"],null]": { src: "/audio/chapter8/8-3-017.mp3" },
  "[\"SUBSTITUTE — tan 45° = 1, so tan²45° = 1² = 1 in both places. Start with the numerator.\",[\"top = 1 − 1\",\"top = 0\"],null]": { src: "/audio/chapter8/8-3-018.mp3" },
  "[\"CALCULATE, LINE 1 — use the plus sign in the denominator: 1 + 1 = 2. The denominator is not zero, so the fraction is defined.\",[\"bottom = 1 + 1\",\"bottom = 2\"],null]": { src: "/audio/chapter8/8-3-019.mp3" },
  "[\"CALCULATE, LINE 2 — place the finished numerator over the finished denominator, then divide.\",[\"= 0 / 2\",\"= 0\"],null]": { src: "/audio/chapter8/8-3-020.mp3" },
  "[\"SANITY CHECK — a zero numerator over a non-zero denominator must equal zero. It cannot be undefined because the denominator is 2.\",[\"0 ÷ 2 = 0 ✓\",\"denominator 2 ≠ 0 ✓\"],null]": { src: "/audio/chapter8/8-3-021.mp3" },
  "[\"FINAL ANSWER — option (D), 0.\",[\"(1 − tan²45°)/(1 + tan²45°) = 0\"],\"(D) 0\"]": { src: "/audio/chapter8/8-3-022.mp3" },
  "[\"Imagine an equilateral pizza slice folded exactly down its middle. Before the fold lands, predict: will the base split into equal pieces? Call every full side 2a.\",[\"PREDICT\",\"fold line ⇒ equal halves?\",\"all sides = 2a\"],null]": { src: "/audio/chapter8/8-3-023.mp3" },
  "[\"Drop the fold line from A straight down to the base. It lands at 90°, turning one equilateral shape into two matching right triangles.\",[\"AD ⊥ BC\"],null]": { src: "/audio/chapter8/8-3-024.mp3" },
  "[\"Reveal: the two folded halves match, so D is the exact midpoint. BD and DC are each half of 2a, which is a.\",[\"BD = DC = a\",\"the halves match\"],null]": { src: "/audio/chapter8/8-3-025.mp3" },
  "[\"It also splits the 60° angle at A into two equal parts, so the angle at the top of our half-triangle is 30°.\",[\"∠BAD = 30°\",\"∠ABD = 60°\"],null]": { src: "/audio/chapter8/8-3-026.mp3" },
  "[\"Pythagoras on the half-triangle gives the height. That is every length we need.\",[\"AD² = (2a)² − a²\",\"AD² = 3a²\",\"AD = a√3\"],null]": { src: "/audio/chapter8/8-3-027.mp3" },
  "[\"Prediction checkpoint: stand at 30° and point to opposite, adjacent and hypotenuse before reading. The short a faces you, tall a√3 sits beside you, and 2a is across the right angle.\",[\"sin 30° = a/2a = 1/2\",\"cos 30° = a√3/2a = √3/2\",\"tan 30° = a/(a√3) = 1/√3\"],null]": { src: "/audio/chapter8/8-3-028.mp3" },
  "[\"Now stand at the 60° corner instead. Nothing about the triangle changed — only which side counts as opposite and which as adjacent, so the two values simply swap.\",[\"sin 60° = a√3/2a = √3/2\",\"cos 60° = a/2a = 1/2\",\"tan 60° = a√3/a = √3\"],\"30° and 60° swap sin and cos\"]": { src: "/audio/chapter8/8-3-029.mp3" },
  "[\"READ & TRANSLATE — NCERT Exercise 8.2, Q1(i) asks for one number. It contains two products: sin 60° times cos 30°, plus sin 30° times cos 60°.\",[\"sin 60° cos 30°\",\"+ sin 30° cos 60°\"],null]": { src: "/audio/chapter8/8-3-030.mp3" },
  "[\"CHOOSE THE PATTERN — all four are standard-angle values, so use Table 8.1. Keep the two products in separate lanes and add only after both are finished.\",[\"1. substitute\",\"2. multiply each pair\",\"3. add\"],null]": { src: "/audio/chapter8/8-3-031.mp3" },
  "[\"SUBSTITUTE — copy each value into its exact place, keeping the multiplication signs and the central plus sign.\",[\"sin 60° = √3/2\",\"cos 30° = √3/2\",\"sin 30° = 1/2\",\"cos 60° = 1/2\"],null]": { src: "/audio/chapter8/8-3-032.mp3" },
  "[\"CALCULATE, LINE 1 — first product: multiply numerator by numerator and denominator by denominator. √3 × √3 = 3.\",[\"(√3/2)(√3/2)\",\"= 3/4\"],null]": { src: "/audio/chapter8/8-3-033.mp3" },
  "[\"CALCULATE, LINE 2 — second product: 1 × 1 on top and 2 × 2 below gives 1/4.\",[\"(1/2)(1/2)\",\"= 1/4\"],null]": { src: "/audio/chapter8/8-3-034.mp3" },
  "[\"CALCULATE, LINE 3 — the denominators already match, so add the numerators: 3 + 1 = 4.\",[\"3/4 + 1/4\",\"= 4/4\"],null]": { src: "/audio/chapter8/8-3-035.mp3" },
  "[\"SANITY CHECK — both products are positive and each is below 1; 3/4 + 1/4 fills one whole. The result 1 is plausible and exact.\",[\"0 < 3/4 < 1\",\"0 < 1/4 < 1\",\"sum = 1 ✓\"],null]": { src: "/audio/chapter8/8-3-036.mp3" },
  "[\"FINAL ANSWER — sin 60° cos 30° + sin 30° cos 60° = 1.\",[\"4/4 = 1\"],\"= 1\"]": { src: "/audio/chapter8/8-3-037.mp3" },
  "[\"READ & TRANSLATE — NCERT Exercise 8.2, Q2(i) asks which option has the same value as this fraction. The numerator is 2 tan 30°; the whole bracket 1 + tan²30° is the denominator.\",[\"2 tan 30°\",\"⁄\",\"(1 + tan²30°)\"],null]": { src: "/audio/chapter8/8-3-038.mp3" },
  "[\"CHOOSE THE PATTERN — use direct substitution because tan 30° is a table value. Reduce the expression to a number first, then match that number to an option.\",[\"tan 30° = 1/√3\"],null]": { src: "/audio/chapter8/8-3-039.mp3" },
  "[\"SUBSTITUTE, NUMERATOR — replace tan 30° with 1/√3, then multiply by 2.\",[\"2 × 1/√3\",\"= 2/√3\"],null]": { src: "/audio/chapter8/8-3-040.mp3" },
  "[\"SUBSTITUTE, DENOMINATOR — square 1/√3 first to get 1/3, then add 1 using denominator 3.\",[\"1 + 1/3\",\"= 4/3\"],null]": { src: "/audio/chapter8/8-3-041.mp3" },
  "[\"CALCULATE, ONE LINE AT A TIME — dividing by 4/3 means multiplying by 3/4; then cancel common factors.\",[\"(2/√3) × (3/4)\",\"= 6/(4√3)\",\"= 3/(2√3)\"],null]": { src: "/audio/chapter8/8-3-042.mp3" },
  "[\"CALCULATE, FINAL LINE — rationalise 3/(2√3) by multiplying top and bottom by √3. The value becomes √3/2.\",[\"3√3/(2 × 3)\",\"= √3/2\"],null]": { src: "/audio/chapter8/8-3-043.mp3" },
  "[\"SANITY CHECK — the original numerator is about 1.15 and denominator about 1.33, so the answer should be below 1. √3/2 ≈ 0.87 fits.\",[\"1.15/1.33 ≈ 0.87\",\"√3/2 ≈ 0.87 ✓\"],null]": { src: "/audio/chapter8/8-3-044.mp3" },
  "[\"FINAL ANSWER — √3/2 is sin 60°, so choose option (A).\",[\"√3/2 = sin 60°\"],\"(A) sin 60°\"]": { src: "/audio/chapter8/8-3-045.mp3" },
  "[\"READ & TRANSLATE — NCERT Exercise 8.2, Q2(iv) asks which option matches the fraction. It looks like Q2(i), but the denominator contains 1 minus tan²30°.\",[\"2 tan 30°\",\"⁄\",\"(1 − tan²30°)\"],null]": { src: "/audio/chapter8/8-3-046.mp3" },
  "[\"CHOOSE THE PATTERN — again substitute tan 30° = 1/√3, but box the minus sign. A smaller denominator should make this answer larger than Q2(i).\",[\"same top\",\"minus on the bottom\"],null]": { src: "/audio/chapter8/8-3-047.mp3" },
  "[\"SUBSTITUTE, NUMERATOR — replace tan 30° with 1/√3. The top is unchanged from Q2(i).\",[\"2 × 1/√3\",\"= 2/√3\"],null]": { src: "/audio/chapter8/8-3-048.mp3" },
  "[\"SUBSTITUTE, DENOMINATOR — square first, then subtract: 1 − 1/3 = 3/3 − 1/3 = 2/3.\",[\"1 − 1/3\",\"= 2/3\"],null]": { src: "/audio/chapter8/8-3-049.mp3" },
  "[\"CALCULATE, ONE LINE AT A TIME — divide by 2/3 by multiplying by 3/2, cancel the 2s, then simplify the root.\",[\"(2/√3) × (3/2)\",\"= 3/√3\",\"= √3\"],null]": { src: "/audio/chapter8/8-3-050.mp3" },
  "[\"SANITY CHECK — the denominator 2/3 is smaller than 1, so dividing 2/√3 by it must increase the value. √3 ≈ 1.73 is larger than 2/√3 ≈ 1.15.\",[\"2/3 < 1\",\"1.73 > 1.15 ✓\"],null]": { src: "/audio/chapter8/8-3-051.mp3" },
  "[\"FINAL ANSWER — √3 sits under 60° in the tangent row, so choose option (C), tan 60°.\",[\"√3 = tan 60°\"],\"(C) tan 60°\"]": { src: "/audio/chapter8/8-3-052.mp3" },
  "[\"READ & TRANSLATE — NCERT Exercise 8.2, Q2(iii) asks which listed angle makes the left side sin(2A) equal the right side 2 × sin A. Doubling the angle is not the same as doubling the sine.\",[\"sin 2A = 2 sin A\",\"which A?\"],null]": { src: "/audio/chapter8/8-3-061.mp3" },
  "[\"CHOOSE THE PATTERN — there is no valid rule sin 2A = 2 sin A, so use option testing. Substitute an angle into both sides and compare the two numbers.\",[\"test each option\",\"compare both sides\"],null]": { src: "/audio/chapter8/8-3-062.mp3" },
  "[\"SUBSTITUTE A = 30° — first double the angle inside sine, then separately multiply the sine value on the right.\",[\"LHS = √3/2 ≈ 0.87\",\"RHS = 2(1/2) = 1\",\"not equal\"],null]": { src: "/audio/chapter8/8-3-063.mp3" },
  "[\"CALCULATE THE NEXT OPTION — for A = 45°, 2A = 90°. Evaluate each side one line at a time.\",[\"LHS = sin 90° = 1\",\"RHS = 2(1/√2) ≈ 1.41\",\"not equal\"],null]": { src: "/audio/chapter8/8-3-064.mp3" },
  "[\"SUBSTITUTE A = 0° — doubling zero still gives zero, and multiplying sin 0° by 2 still gives zero.\",[\"LHS = sin 0° = 0\",\"RHS = 2(0) = 0\",\"equal ✓\"],null]": { src: "/audio/chapter8/8-3-065.mp3" },
  "[\"SANITY CHECK — option 60° cannot work because its right side is 2 sin 60° = √3, which is greater than 1, while every sine value stays between −1 and 1.\",[\"RHS at 60° = √3 > 1\",\"but |sin 120°| ≤ 1 ✓\"],null]": { src: "/audio/chapter8/8-3-066.mp3" },
  "[\"FINAL ANSWER — option (A), A = 0°. The equation works there because both sides equal zero; sin 2A is not generally 2 sin A.\",[\"0 = 0 ✓\",\"sin 2A ≠ 2 sin A in general\"],\"(A) A = 0°\"]": { src: "/audio/chapter8/8-3-067.mp3" },
  "[\"READ & TRANSLATE — NCERT Exercise 8.2, Q4(v) asks whether the claim 'cot A is not defined at A = 0°' is true or false, and it requires a reason.\",[\"claim: cot 0°\",\"is not defined\"],null]": { src: "/audio/chapter8/8-3-068.mp3" },
  "[\"CHOOSE THE FORMULA — use cot A = cos A/sin A because both sine and cosine at 0° are known. A fraction is defined only when its denominator is non-zero.\",[\"cot A = cos A / sin A\"],null]": { src: "/audio/chapter8/8-3-069.mp3" },
  "[\"SUBSTITUTE — Table 8.1 gives cos 0° = 1 and sin 0° = 0. Place them into numerator and denominator in that order.\",[\"cos 0° = 1\",\"sin 0° = 0\"],null]": { src: "/audio/chapter8/8-3-070.mp3" },
  "[\"CALCULATE — cot 0° becomes 1/0. Division asks 'what number times 0 gives 1?' No number can, so the value is undefined.\",[\"cot 0° = 1 / 0\",\"no such number\"],null]": { src: "/audio/chapter8/8-3-071.mp3" },
  "[\"SANITY CHECK — compare tan 0° = sin 0°/cos 0° = 0/1 = 0. Zero on top is safe; zero underneath is what breaks cot.\",[\"tan 0° = 0/1 = 0\",\"cot 0° = 1/0 = n.d. ✓\"],null]": { src: "/audio/chapter8/8-3-072.mp3" },
  "[\"FINAL ANSWER — the statement is True: cot 0° is not defined.\",[\"cot 0° = 1/0\",\"not defined\"],\"True · undefined\"]": { src: "/audio/chapter8/8-3-073.mp3" },
  "[\"Treat Table 8.1 like a pattern machine, not a wall of thirty facts. Before we switch it on, predict which row should climb as a ramp opens from 0° to 90°.\",[\"PREDICT\",\"sin climbs or falls?\",\"cos climbs or falls?\"],null]": { src: "/audio/chapter8/8-3-074.mp3" },
  "[\"Reveal: sine is the height gauge on our ramp, so it climbs from 0 to 1 as the angle opens. The first row fills in from left to right.\",[\"from the triangles\",\"we just built\"],null]": { src: "/audio/chapter8/8-3-075.mp3" },
  "[\"Feed the pattern machine 0, 1, 2, 3, 4. Divide each by 4 and take the square root; out comes the entire sine row.\",[\"√(0/4)  √(1/4)  √(2/4)\",\"√(3/4)  √(4/4)\",\"= the sine row\"],null]": { src: "/audio/chapter8/8-3-076.mp3" },
  "[\"Prediction checkpoint: what happens if the machine runs backwards? The cosine row appears. You do not memorise it separately — reverse sine.\",[\"cos = sin reversed\"],null]": { src: "/audio/chapter8/8-3-077.mp3" },
  "[\"Tangent is sine divided by cosine, entry by entry. At 90° that means dividing by zero, which is why it is not defined there.\",[\"tan = sin / cos\",\"at 90°: 1/0\",\"not defined\"],null]": { src: "/audio/chapter8/8-3-078.mp3" },
  "[\"The last three rows are just the first three flipped upside down. Wherever a value was 0, its flip is undefined.\",[\"cosec = 1/sin\",\"sec = 1/cos\",\"cot = 1/tan\"],null]": { src: "/audio/chapter8/8-3-079.mp3" },
  "[\"Read across and the pattern is the real takeaway: sine climbs from 0 to 1 while cosine falls from 1 to 0. They cross at 45°, the one angle where they are equal.\",[\"sin ↑  0 → 1\",\"cos ↓  1 → 0\",\"equal at 45°\"],\"one pattern, whole table\"]": { src: "/audio/chapter8/8-3-080.mp3" },
  "[\"READ & TRANSLATE — NCERT Example 6 gives a right triangle with AB = 5 cm and angle C = 30°. Mark 5 on the side opposite C, then mark BC and AC as the two unknowns.\",[\"AB = 5 cm\",\"∠C = 30°\",\"find BC, AC\"],null]": { src: "/audio/chapter8/8-3-081.mp3" },
  "[\"CHOOSE THE FORMULA — for each unknown, pair it with the known side AB. Opposite plus adjacent chooses tangent for BC; opposite plus hypotenuse chooses sine for AC.\",[\"1. name the sides\",\"2. pick the ratio\",\"3. solve\"],null]": { src: "/audio/chapter8/8-3-082.mp3" },
  "[\"TRANSLATE THE DIAGRAM — stand at C: AB faces you, so opposite = 5; BC touches C without crossing the right angle, so adjacent = BC.\",[\"opposite = AB = 5\",\"adjacent = BC = ?\"],null]": { src: "/audio/chapter8/8-3-083.mp3" },
  "[\"SUBSTITUTE FOR BC — write tan C = opposite/adjacent, then replace C with 30°, opposite with 5 and tan 30° with 1/√3.\",[\"tan 30° = AB / BC\",\"1/√3 = 5 / BC\"],null]": { src: "/audio/chapter8/8-3-084.mp3" },
  "[\"CALCULATE BC, ONE LINE AT A TIME — cross-multiply, then isolate BC.\",[\"BC/√3 = 5\",\"BC = 5√3 cm\"],null]": { src: "/audio/chapter8/8-3-085.mp3" },
  "[\"SUBSTITUTE AND CALCULATE AC — opposite and hypotenuse choose sine. Replace sin 30° with 1/2, cross-multiply, then divide by 1.\",[\"sin 30° = AB / AC\",\"1/2 = 5 / AC\",\"AC = 10 cm\"],null]": { src: "/audio/chapter8/8-3-086.mp3" },
  "[\"SANITY CHECK — Pythagoras must reproduce the hypotenuse. 5² + (5√3)² = 25 + 75 = 100, and √100 = 10.\",[\"√(25 + 75)\",\"= √100 = 10 ✓\"],null]": { src: "/audio/chapter8/8-3-087.mp3" },
  "[\"FINAL ANSWER — BC = 5√3 cm and AC = 10 cm.\",[\"BC = 5√3 cm\",\"AC = 10 cm\"],\"BC = 5√3 cm · AC = 10 cm\"]": { src: "/audio/chapter8/8-3-088.mp3" },
  "[\"READ & TRANSLATE — NCERT Example 7 gives PQ = 3 cm and hypotenuse PR = 6 cm, then asks for both acute angles. We need a side ratio first, then an angle.\",[\"PQ = 3 cm\",\"PR = 6 cm\",\"find both angles\"],null]": { src: "/audio/chapter8/8-3-089.mp3" },
  "[\"CHOOSE THE FORMULA — relative to angle R, the known sides are opposite PQ and hypotenuse PR, so sine is the only ratio using exactly those two sides.\",[\"sides → ratio\",\"ratio → angle\"],null]": { src: "/audio/chapter8/8-3-090.mp3" },
  "[\"SUBSTITUTE — place the two given lengths into sin R = opposite/hypotenuse.\",[\"sin R = PQ / PR\",\"sin R = 3 / 6\"],null]": { src: "/audio/chapter8/8-3-091.mp3" },
  "[\"CALCULATE, LINE 1 — simplify 3/6 to 1/2, then read Table 8.1 backwards: sine equals 1/2 at 30°.\",[\"sin R = 1/2\",\"∠R = 30°\"],null]": { src: "/audio/chapter8/8-3-092.mp3" },
  "[\"CALCULATE, LINE 2 — the two acute angles in a right triangle add to 90°, so subtract R from 90° to get P.\",[\"∠P = 90° − 30°\",\"∠P = 60°\"],null]": { src: "/audio/chapter8/8-3-093.mp3" },
  "[\"SANITY CHECK — the side opposite 30° should be half the hypotenuse. PQ = 3 is exactly half of PR = 6, and 30° + 60° + 90° = 180°.\",[\"3 = 6/2 ✓\",\"30° + 60° + 90° = 180° ✓\"],null]": { src: "/audio/chapter8/8-3-094.mp3" },
  "[\"FINAL ANSWER — angle PRQ = 30° and angle QPR = 60°.\",[\"∠PRQ = 30°\",\"∠QPR = 60°\"],\"∠PRQ = 30° · ∠QPR = 60°\"]": { src: "/audio/chapter8/8-3-095.mp3" },
  "[\"READ & TRANSLATE — NCERT Example 8 gives two ratio statements and asks for two angles. The range and A > B tell us both angle expressions are valid standard angles.\",[\"sin(A−B) = 1/2\",\"cos(A+B) = 1/2\"],null]": { src: "/audio/chapter8/8-3-096.mp3" },
  "[\"CHOOSE THE PATTERN — read Table 8.1 backwards to turn each ratio value into an angle. Then solve the resulting simultaneous equations by adding and substituting.\",[\"ratio → angle\",\"then solve the pair\"],null]": { src: "/audio/chapter8/8-3-097.mp3" },
  "[\"SUBSTITUTE FROM THE SINE ROW — sin of an allowed angle is 1/2 at 30°, so replace the first ratio statement with A − B = 30°.\",[\"A − B = 30°\",\"…(1)\"],null]": { src: "/audio/chapter8/8-3-098.mp3" },
  "[\"SUBSTITUTE FROM THE COSINE ROW — cos of an allowed angle is 1/2 at 60°, so A + B = 60°.\",[\"A + B = 60°\",\"…(2)\"],null]": { src: "/audio/chapter8/8-3-099.mp3" },
  "[\"CALCULATE, LINE 1 — add the equations vertically. −B and +B cancel, leaving 2A = 90°; divide both sides by 2.\",[\"2A = 90°\",\"A = 45°\"],null]": { src: "/audio/chapter8/8-3-100.mp3" },
  "[\"CALCULATE, LINE 2 — substitute A = 45° into A + B = 60°, then subtract 45°.\",[\"45° + B = 60°\",\"B = 15°\"],null]": { src: "/audio/chapter8/8-3-101.mp3" },
  "[\"SANITY CHECK — put both answers back: A − B = 30° gives sin 30° = 1/2, and A + B = 60° gives cos 60° = 1/2.\",[\"45° − 15° = 30° ✓\",\"45° + 15° = 60° ✓\"],null]": { src: "/audio/chapter8/8-3-102.mp3" },
  "[\"READ & TRANSLATE — NCERT Exercise 8.2, Q3 gives two tangent values and asks for A and B. The conditions select the standard acute angles in Table 8.1.\",[\"tan(A+B) = √3\",\"tan(A−B) = 1/√3\"],null]": { src: "/audio/chapter8/8-3-104.mp3" },
  "[\"CHOOSE THE PATTERN — read the tangent row backwards, then use simultaneous equations: add to isolate A and subtract to isolate B.\",[\"same method\",\"different row\"],null]": { src: "/audio/chapter8/8-3-105.mp3" },
  "[\"SUBSTITUTE FROM TABLE 8.1 — tan 60° = √3 and tan 30° = 1/√3, so replace each ratio statement with its angle equation.\",[\"A + B = 60°  …(1)\",\"A − B = 30°  …(2)\"],null]": { src: "/audio/chapter8/8-3-106.mp3" },
  "[\"CALCULATE A — add equations (1) and (2). The B terms cancel; divide 2A = 90° by 2.\",[\"2A = 90°\",\"A = 45°\"],null]": { src: "/audio/chapter8/8-3-107.mp3" },
  "[\"CALCULATE B — subtract equation (2) from equation (1). The A terms cancel; divide 2B = 30° by 2.\",[\"2B = 30°\",\"B = 15°\"],null]": { src: "/audio/chapter8/8-3-108.mp3" },
  "[\"SANITY CHECK — 45° + 15° = 60° gives tan = √3, and 45° − 15° = 30° gives tan = 1/√3. Both original statements return.\",[\"tan 60° = √3 ✓\",\"tan 30° = 1/√3 ✓\"],null]": { src: "/audio/chapter8/8-3-109.mp3" },
  "[\"Think of an identity as a balance that stays level no matter where the angle slider moves. Predict: will sin A = 1/2 stay balanced for every angle, or only one?\",[\"PREDICT\",\"one angle or every angle?\"],null]": { src: "/audio/chapter8/8-4-001.mp3" },
  "[\"Reveal: sin A = 1/2 works only at particular angles. Our always-balanced machine starts instead from Pythagoras on a right triangle; the rest is division.\",[\"AB² + BC² = AC²\"],null]": { src: "/audio/chapter8/8-4-002.mp3" },
  "[\"Prediction checkpoint: divide every tray of the balance by AC². Which familiar ratios will AB/AC and BC/AC become?\",[\"÷ AC²\",\"AB/AC = cos A\",\"BC/AC = sin A\"],null]": { src: "/audio/chapter8/8-4-003.mp3" },
  "[\"That is the first identity, and the one you will use most often. It holds for every angle from 0° to 90°.\",[\"cos²A + sin²A = 1\"],\"sin²A + cos²A = 1\"]": { src: "/audio/chapter8/8-4-004.mp3" },
  "[\"Run the same balance through a different setting: divide every term by adjacent². Predict the pair whose denominator is adjacent — tan and sec.\",[\"÷ AB²\",\"BC/AB = tan A\",\"AC/AB = sec A\"],null]": { src: "/audio/chapter8/8-4-005.mp3" },
  "[\"The second identity. It stops just short of 90°, because tan and sec do not exist there.\",[\"1 + tan²A = sec²A\",\"0° ≤ A < 90°\"],\"1 + tan²A = sec²A\"]": { src: "/audio/chapter8/8-4-006.mp3" },
  "[\"One machine setting remains: divide every term by opposite². Before the labels appear, predict which ratios put opposite underneath.\",[\"÷ BC²\",\"AB/BC = cot A\",\"AC/BC = cosec A\"],null]": { src: "/audio/chapter8/8-4-007.mp3" },
  "[\"The third identity, undefined at 0° for the same reason. Three identities, one theorem, three divisions — that is the whole of §8.4.\",[\"cot²A + 1 = cosec²A\",\"0° < A ≤ 90°\"],\"one Pythagoras → three identities\"]": { src: "/audio/chapter8/8-4-008.mp3" },
  "[\"Learn the rearranged forms too — these are the shapes you will actually reach for mid-proof.\",[\"sin² = 1 − cos²\",\"tan² = sec² − 1\",\"cot² = cosec² − 1\"],null]": { src: "/audio/chapter8/8-4-009.mp3" },
  "[\"READ & TRANSLATE — NCERT Example 9 gives sin A as the only allowed building block. Rewrite cos A, tan A and sec A without any other trig ratio in the final forms.\",[],null]": { src: "/audio/chapter8/8-4-010.mp3" },
  "[\"CHOOSE THE FORMULAS — identity 1 contains both sin and cos, so use it to isolate cos. Then use tan = sin/cos and sec = 1/cos because both depend on that cosine.\",[],null]": { src: "/audio/chapter8/8-4-011.mp3" },
  "[\"SUBSTITUTE THE IDENTITY — start with sin²A + cos²A = 1 and subtract sin²A from both sides, one line at a time.\",[],null]": { src: "/audio/chapter8/8-4-012.mp3" },
  "[\"CALCULATE cos A — take the square root of the whole right side. A is acute, so cos A is positive and we keep the positive root.\",[],null]": { src: "/audio/chapter8/8-4-013.mp3" },
  "[\"SUBSTITUTE AND CALCULATE tan A — put the new expression for cos A into tan A = sin A/cos A.\",[],null]": { src: "/audio/chapter8/8-4-014.mp3" },
  "[\"SUBSTITUTE AND CALCULATE sec A — put the same cosine expression into sec A = 1/cos A.\",[],null]": { src: "/audio/chapter8/8-4-015.mp3" },
  "[\"SANITY CHECK — try A = 30°, where sin A = 1/2. The formulas return cos A = √3/2, tan A = 1/√3 and sec A = 2/√3, matching Table 8.1.\",[],null]": { src: "/audio/chapter8/8-4-016.mp3" },
  "[\"FINAL ANSWER — all three ratios are now written only in terms of sin A.\",[],\"all three in terms of sin A\"]": { src: "/audio/chapter8/8-4-017.mp3" },
  "[\"READ & TRANSLATE — NCERT Exercise 8.3, Q3(i) asks for one constant value. Both terms have factor 9, and the remaining squared ratios are sec and tan.\",[],null]": { src: "/audio/chapter8/8-4-018.mp3" },
  "[\"CHOOSE THE PATTERN — factor instead of substituting an angle because sec²A − tan²A is identity 2 rearranged and is constant for every allowed A.\",[],null]": { src: "/audio/chapter8/8-4-019.mp3" },
  "[\"SUBSTITUTE THE COMMON FACTOR — write 9 outside one bracket, leaving sec²A − tan²A inside.\",[],null]": { src: "/audio/chapter8/8-4-020.mp3" },
  "[\"CALCULATE, LINE 1 — rearrange 1 + tan²A = sec²A by subtracting tan²A, then replace the bracket with 1.\",[],null]": { src: "/audio/chapter8/8-4-021.mp3" },
  "[\"CALCULATE, LINE 2 — multiply the outside factor by the identity value.\",[],null]": { src: "/audio/chapter8/8-4-022.mp3" },
  "[\"SANITY CHECK — use A = 45°: sec²45° = 2 and tan²45° = 1, so 9(2) − 9(1) = 18 − 9 = 9.\",[],null]": { src: "/audio/chapter8/8-4-023.mp3" },
  "[\"FINAL ANSWER — option (B), 9.\",[],\"(B) 9\"]": { src: "/audio/chapter8/8-4-024.mp3" },
  "[\"READ & TRANSLATE — NCERT Exercise 8.3, Q3(iv) asks which option equals a fraction whose numerator is 1 + tan²A and denominator is 1 + cot²A.\",[],null]": { src: "/audio/chapter8/8-4-025.mp3" },
  "[\"CHOOSE THE PATTERN — both complete brackets match identities: 1 + tan²A = sec²A and 1 + cot²A = cosec²A. Replacing whole patterns avoids long algebra.\",[],null]": { src: "/audio/chapter8/8-4-026.mp3" },
  "[\"SUBSTITUTE THE IDENTITIES — replace the numerator and denominator as complete units.\",[],null]": { src: "/audio/chapter8/8-4-027.mp3" },
  "[\"SUBSTITUTE RECIPROCALS — sec²A = 1/cos²A and cosec²A = 1/sin²A.\",[],null]": { src: "/audio/chapter8/8-4-028.mp3" },
  "[\"CALCULATE, ONE LINE AT A TIME — flip the divisor, cancel the 1s, and recognise sin²A/cos²A as tan²A.\",[],null]": { src: "/audio/chapter8/8-4-029.mp3" },
  "[\"SANITY CHECK — at A = 45°, tan²A = cot²A = 1. The original fraction is (1 + 1)/(1 + 1) = 1, matching tan²45°.\",[],null]": { src: "/audio/chapter8/8-4-030.mp3" },
  "[\"FINAL ANSWER — option (D), tan²A.\",[],\"(D) tan²A\"]": { src: "/audio/chapter8/8-4-031.mp3" },
  "[\"Put on a proof-detective hat: the left and right sides are two suspects claiming to be the same expression. Predict the fair test — change one suspect step-by-step, or secretly move evidence across the equals sign?\",[],null]": { src: "/audio/chapter8/8-4-032.mp3" },
  "[\"Reveal: transform one side only. Start with the messier suspect because it carries more clues to simplify; never move evidence across the equals sign.\",[],null]": { src: "/audio/chapter8/8-4-033.mp3" },
  "[\"Translation clue: if tan, cot, sec and cosec are all talking at once, convert them into the common language of sin and cos.\",[],null]": { src: "/audio/chapter8/8-4-034.mp3" },
  "[\"Prediction checkpoint: a common factor is hiding in both numerator and denominator. Expanding scatters the clue; factoring makes the matching pieces visible so they can cancel.\",[],null]": { src: "/audio/chapter8/8-4-035.mp3" },
  "[\"Rule four: combine fractions over a common denominator. The numerator that appears is very often 1, or sin² + cos².\",[],null]": { src: "/audio/chapter8/8-4-036.mp3" },
  "[\"Use the conjugate key: pair (1 + sin A) with (1 − sin A). Predict the product before revealing it — the middle terms vanish and identity 1 appears.\",[],null]": { src: "/audio/chapter8/8-4-037.mp3" },
  "[\"Rule six, for when a proof stalls: force an identity to appear. sec − tan and sec + tan multiply to 1, and so do cosec − cot and cosec + cot.\",[],\"six moves cover every proof in the exercise\"]": { src: "/audio/chapter8/8-4-038.mp3" },
  "[\"READ & TRANSLATE — NCERT Example 10 asks us to prove a complicated left side equals the constant 1 for every allowed A. This is a proof, so we transform the LHS only.\",[],null]": { src: "/audio/chapter8/8-4-039.mp3" },
  "[\"CHOOSE THE FORMULAS — use sec A = 1/cos A and tan A = sin A/cos A because one common denominator will expose conjugates (1 − sin A)(1 + sin A).\",[],null]": { src: "/audio/chapter8/8-4-040.mp3" },
  "[\"SUBSTITUTE — replace every sec and tan on the LHS with its sine-cosine form, without touching the RHS.\",[],null]": { src: "/audio/chapter8/8-4-041.mp3" },
  "[\"CALCULATE, LINE 1 — combine the last bracket over cos A, then multiply the two cosine denominators to get cos²A.\",[],null]": { src: "/audio/chapter8/8-4-042.mp3" },
  "[\"CALCULATE, LINE 2 — multiply the conjugates. (1 − sin A)(1 + sin A) is 1 − sin²A because the middle terms cancel.\",[],null]": { src: "/audio/chapter8/8-4-043.mp3" },
  "[\"CALCULATE, LINE 3 — substitute 1 − sin²A = cos²A, then cancel cos²A/cos²A.\",[],null]": { src: "/audio/chapter8/8-4-044.mp3" },
  "[\"SANITY CHECK — at A = 30°, sec A = 2/√3, sin A = 1/2 and tan A = 1/√3. The original LHS becomes (2/√3)(1/2)(√3) = 1.\",[],null]": { src: "/audio/chapter8/8-4-045.mp3" },
  "[\"READ & TRANSLATE — NCERT Example 11 asks us to turn the cot-and-cos fraction on the LHS into the cosec fraction on the RHS, without moving terms across the equals sign.\",[],null]": { src: "/audio/chapter8/8-4-047.mp3" },
  "[\"CHOOSE THE FORMULA — use cot A = cos A/sin A. That makes cos A a common factor in both numerator and denominator, so factoring will create a cancellation.\",[],null]": { src: "/audio/chapter8/8-4-048.mp3" },
  "[\"SUBSTITUTE — replace each cot A with cos A/sin A on the LHS; keep numerator and denominator on separate lines.\",[],null]": { src: "/audio/chapter8/8-4-049.mp3" },
  "[\"CALCULATE, LINE 1 — factor cos A from the numerator and separately from the denominator.\",[],null]": { src: "/audio/chapter8/8-4-050.mp3" },
  "[\"CALCULATE, LINE 2 — cancel the same non-zero factor cos A from top and bottom.\",[],null]": { src: "/audio/chapter8/8-4-051.mp3" },
  "[\"CALCULATE, LINE 3 — substitute 1/sin A = cosec A. The transformed LHS now matches the RHS symbol for symbol.\",[],null]": { src: "/audio/chapter8/8-4-052.mp3" },
  "[\"SANITY CHECK — at A = 45°, cot A = 1, cos A = 1/√2 and cosec A = √2. Both sides become (√2 − 1)/(√2 + 1).\",[],null]": { src: "/audio/chapter8/8-4-053.mp3" },
  "[\"FINAL ANSWER — the LHS becomes the RHS exactly; hence the identity is proved.\",[],\"proved\"]": { src: "/audio/chapter8/8-4-054.mp3" },
  "[\"READ & TRANSLATE — NCERT Exercise 8.3, Q4(i) asks us to transform the squared cosec-cot expression on the LHS into the cosine fraction on the RHS.\",[],null]": { src: "/audio/chapter8/8-4-055.mp3" },
  "[\"CHOOSE THE FORMULAS — start with the messier LHS, use cosec θ = 1/sin θ and cot θ = cos θ/sin θ, then use sin²θ = 1 − cos²θ so a factor can cancel.\",[],null]": { src: "/audio/chapter8/8-4-056.mp3" },
  "[\"SUBSTITUTE — replace both ratios, combine their common denominator inside the bracket, and then square numerator and denominator.\",[],null]": { src: "/audio/chapter8/8-4-057.mp3" },
  "[\"CALCULATE, LINE 1 — substitute sin²θ = 1 − cos²θ, then factor the difference of squares into (1 − cos θ)(1 + cos θ).\",[],null]": { src: "/audio/chapter8/8-4-058.mp3" },
  "[\"CALCULATE, LINE 2 — cancel one common factor (1 − cos θ). The remaining fraction matches the RHS.\",[],null]": { src: "/audio/chapter8/8-4-059.mp3" },
  "[\"SANITY CHECK — at θ = 60°, the LHS is (2/√3 − 1/√3)² = 1/3. The RHS is (1 − 1/2)/(1 + 1/2) = 1/3 too.\",[],null]": { src: "/audio/chapter8/8-4-060.mp3" },
  "[\"FINAL ANSWER — the LHS simplifies exactly to the RHS; hence the identity is proved.\",[],\"proved\"]": { src: "/audio/chapter8/8-4-061.mp3" },
  "[\"READ & TRANSLATE — NCERT Exercise 8.3, Q4(ii) asks us to combine two fractions on the LHS until they become 2 sec A on the RHS.\",[],null]": { src: "/audio/chapter8/8-4-062.mp3" },
  "[\"CHOOSE THE PATTERN — use the common denominator cos A(1 + sin A) because the LHS is a sum of fractions. Expanding only the numerator will expose sin²A + cos²A.\",[],null]": { src: "/audio/chapter8/8-4-063.mp3" },
  "[\"SUBSTITUTE THE COMMON DENOMINATOR — cross-multiply each numerator, keep one shared denominator, then expand (1 + sin A)² one line at a time.\",[],null]": { src: "/audio/chapter8/8-4-064.mp3" },
  "[\"CALCULATE, LINE 1 — group cos²A + sin²A and substitute identity 1. Then factor 2 from 2 + 2 sin A.\",[],null]": { src: "/audio/chapter8/8-4-065.mp3" },
  "[\"CALCULATE, LINE 2 — cancel (1 + sin A), then use 1/cos A = sec A.\",[],null]": { src: "/audio/chapter8/8-4-066.mp3" },
  "[\"SANITY CHECK — at A = 30°, the LHS is √3/3 + √3 = 4√3/3, while 2 sec 30° = 4/√3 = 4√3/3.\",[],null]": { src: "/audio/chapter8/8-4-067.mp3" },
  "[\"FINAL ANSWER — the LHS becomes 2 sec A, exactly the RHS; hence the identity is proved.\",[],\"proved\"]": { src: "/audio/chapter8/8-4-068.mp3" },
  "[\"Final-level map: imagine walking around a right-triangle theme park. Your viewing corner decides the side names. Predict which name never changes as you swap corners.\",[\"sin = opp/hyp\",\"cos = adj/hyp\",\"tan = opp/adj\"],null]": { src: "/audio/chapter8/8-4-069.mp3" },
  "[\"Reveal: the hypotenuse never changes because it always faces the right angle. The other three ratios are simply the first three cards flipped upside down.\",[\"cosec = 1/sin\",\"sec = 1/cos\",\"cot = 1/tan\"],null]": { src: "/audio/chapter8/8-4-070.mp3" },
  "[\"One clue unlocks the whole escape room: a ratio fixes the triangle's shape. Predict the next move after drawing two sides — Pythagoras reveals the third, then all six ratios follow.\",[],null]": { src: "/audio/chapter8/8-4-071.mp3" },
  "[\"At the Table 8.1 checkpoint, use the pattern machine instead of brute memory: build sine, reverse it for cosine, then divide for tangent.\",[],null]": { src: "/audio/chapter8/8-4-072.mp3" },
  "[\"There are firm limits on what these values can be. sin and cos are capped at 1; sec and cosec never drop below it.\",[],null]": { src: "/audio/chapter8/8-4-073.mp3" },
  "[\"And three identities, all of them Pythagoras divided by a different side.\",[],null]": { src: "/audio/chapter8/8-4-074.mp3" },
  "[\"Final proof-detective checkpoint: when algebra stalls, predict which conjugate pair multiplies to 1. These factored forms are the hidden shortcut to the exit.\",[],\"chapter 8 complete\"]": { src: "/audio/chapter8/8-4-075.mp3" },
  "[\"READ & TRANSLATE — evaluate one expression made of two products: sin 30° times cos 60°, plus cos 30° times sin 60°.\",[],null]": { src: "/audio/chapter8/8-4-076.mp3" },
  "[\"CHOOSE THE PATTERN — all angles are in Table 8.1, so use direct substitution. Keep the two products separate until each multiplication is complete.\",[],null]": { src: "/audio/chapter8/8-4-077.mp3" },
  "[\"SUBSTITUTE AND CALCULATE, LINE 1 — sin 30° and cos 60° are both 1/2, so their product is 1/4.\",[],null]": { src: "/audio/chapter8/8-4-078.mp3" },
  "[\"SUBSTITUTE AND CALCULATE, LINE 2 — cos 30° and sin 60° are both √3/2; multiply roots and denominators to get 3/4.\",[],null]": { src: "/audio/chapter8/8-4-079.mp3" },
  "[\"CALCULATE, LINE 3 — add fractions with the same denominator: 1 + 3 over 4 equals 4/4, then 1.\",[],null]": { src: "/audio/chapter8/8-4-080.mp3" },
  "[\"SANITY CHECK — both products are positive and below 1; 1/4 plus 3/4 makes exactly one whole, so the result is plausible.\",[],null]": { src: "/audio/chapter8/8-4-081.mp3" },
  "[\"FINAL ANSWER — the expression equals 1.\",[],\"= 1\"]": { src: "/audio/chapter8/8-4-082.mp3" },
  "[\"READ & TRANSLATE — 5 tan A = 12 gives one ratio for an acute angle. We need sin A + cos A, so first turn the tangent into a right triangle with known legs.\",[\"5 tan A = 12\",\"find sin A + cos A\"],null]": { src: "/audio/chapter8/8-4-083.mp3" },
  "[\"CHOOSE THE FORMULAS — use tan A = opposite/adjacent to choose the legs, Pythagoras for the hypotenuse, then sine and cosine because both use that hypotenuse.\",[\"1. ratio → sides\",\"2. Pythagoras\",\"3. read off\"],null]": { src: "/audio/chapter8/8-4-084.mp3" },
  "[\"SUBSTITUTE THE RATIO — divide 5 tan A = 12 by 5 to get tan A = 12/5. Model opposite = 12k and adjacent = 5k; take k = 1 for the simplest similar triangle.\",[\"tan A = 12/5\",\"opposite = 12k\",\"adjacent = 5k\",\"choose k = 1\"],null]": { src: "/audio/chapter8/8-4-085.mp3" },
  "[\"CALCULATE, LINE 1 — use Pythagoras on legs 12 and 5: square, add, then take the positive square root.\",[\"AC² = 144 + 25\",\"AC² = 169\",\"AC = 13\"],null]": { src: "/audio/chapter8/8-4-086.mp3" },
  "[\"SUBSTITUTE, LINE 2 — read sine as opposite/hypotenuse and cosine as adjacent/hypotenuse from the completed 5-12-13 triangle.\",[\"sin A = 12/13\",\"cos A = 5/13\"],null]": { src: "/audio/chapter8/8-4-087.mp3" },
  "[\"CALCULATE, LINE 3 — the denominators match, so add the numerators 12 + 5.\",[\"12/13 + 5/13\",\"= 17/13\"],null]": { src: "/audio/chapter8/8-4-088.mp3" },
  "[\"SANITY CHECK — sin A = 12/13 and cos A = 5/13 are each below 1, while their squares add to 144/169 + 25/169 = 1. The triangle and ratios are consistent.\",[\"(12/13)² + (5/13)²\",\"= 169/169 = 1 ✓\"],null]": { src: "/audio/chapter8/8-4-089.mp3" },
  "[\"FINAL ANSWER — sin A + cos A = 17/13.\",[\"sin A + cos A = 17/13\"],\"sin A + cos A = 17/13\"]": { src: "/audio/chapter8/8-4-090.mp3" },
  "[\"READ & TRANSLATE — prove that the product (1 − sin²θ) sec²θ on the LHS equals the constant 1 for every allowed θ.\",[],null]": { src: "/audio/chapter8/8-4-091.mp3" },
  "[\"CHOOSE THE FORMULAS — identity 1 gives 1 − sin²θ = cos²θ, and sec²θ = 1/cos²θ. Those two factors will cancel.\",[],null]": { src: "/audio/chapter8/8-4-092.mp3" },
  "[\"SUBSTITUTE — replace the complete bracket 1 − sin²θ with cos²θ; leave sec²θ beside it.\",[],null]": { src: "/audio/chapter8/8-4-093.mp3" },
  "[\"CALCULATE — substitute sec²θ = 1/cos²θ, multiply, then cancel cos²θ from numerator and denominator.\",[],null]": { src: "/audio/chapter8/8-4-094.mp3" },
  "[\"SANITY CHECK — at θ = 60°, 1 − sin²60° = 1/4 and sec²60° = 4. Their product is 1/4 × 4 = 1.\",[],null]": { src: "/audio/chapter8/8-4-095.mp3" },
};
